SELECT DISTINCT CR.DESCRCENCUS FROM VINCULO_EMPRESA_CR V JOIN IMP_CENTRORESULTADO CR ON V.COD_CR = CR.CODCENCUS WHERE (:VAR_DRE_EMP IS NULL OR :VAR_DRE_EMP = '' OR FIND_IN_SET(V.COD_EMPRESA, :VAR_DRE_EMP)) AND (:VAR_DRE_GESTOR_CR IS NULL OR :VAR_DRE_GESTOR_CR = '' OR FIND_IN_SET(CR.CODCENCUS, :VAR_DRE_GESTOR_CR)) AND CR.ANALITICO = 'S' ORDER BY CR.DESCRCENCUS